"""Render auditable Polish reports from measured artifacts; no runtime mutation."""
import json,statistics,math
from pathlib import Path
from collections import defaultdict
A=Path(__file__).resolve().parent;ROOT=A.parents[1]
read=lambda p:json.loads(Path(p).read_text(encoding='utf-8-sig'))
trades=read(A/'trades_enriched.json');runs=read(A/'run_statistics.json');groups=read(A/'subgroup_statistics.json')
facts=read(A/'focused_facts.json');quality=read(A/'data_quality.json');stress=read(A/'matched_trade_cost_stress.json');sensitivity=read(A/'sensitivity.json');wf=read(A/'walk_forward.json');uncertainty=read(A/'uncertainty_sensitivity.json')
def f(v):
 if v is None:return '—'
 if isinstance(v,list):return '['+'; '.join(f(x) for x in v)+']'
 if isinstance(v,float) and 0<abs(v)<.001:return f'{v:.6g}'
 if isinstance(v,float):return f'{v:.3f}'
 return str(v)
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join('---' for _ in headers)+'|']+['| '+' | '.join(f(x).replace('|','/') for x in r)+' |' for r in rows])
def save(name,lines):(A/name).write_text('\n\n'.join(lines)+'\n',encoding='utf-8')
def rr(alias,period):return next(r for r in runs if r['run']==f'validation/{alias}-{period}-base')
def local(alias,period='validation'):return [t for t in trades if t['run']==f'validation/{alias}-{period}-base']
intro='Stan audytu: '+facts['at']+'. Badanie offline; bez nowych zleceń, zmian DEMO, konfiguracji, Execution Engine i Risk Managera. Kwoty w PLN, o ile nie zaznaczono inaczej.'
