table(['Rynek','Okres','N','Netto','PF','Śr. R','SD R','DD H1','Seria strat'],[[a,p,rr(a,p)['n'],rr(a,p)['net'],rr(a,p)['pf'],rr(a,p)['mean_R'],rr(a,p)['sd_R'],rr(a,p)['reported_DD'],rr(a,p)['max_loss_streak']] for a in ('US100','OIL') for p in ('development','validation')]),
